class Whycodes < Formula
  desc "Terminal coding agent written in Rust"
  homepage "https://why.codes"
  version "0.6.0"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/whycorporation/whycodes/releases/download/v0.6.0/whycodes-aarch64-apple-darwin.tar.gz"
      sha256 "7fa699a2dd046e84b4b1d6c0f9b8804d078f4570d5a19cf471a2717fd2a4b6ab"
    end

    on_intel do
      url "https://github.com/whycorporation/whycodes/releases/download/v0.6.0/whycodes-x86_64-apple-darwin.tar.gz"
      sha256 "f78b6a1606d98aa47d0788b5c1d11bb85762980080e6a1da3486d63a1f466434"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/whycorporation/whycodes/releases/download/v0.6.0/whycodes-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "2248d0d1dedae3f3b62dc66accf3da2e18a316b1bc072da766ffc2cdc53014f7"
    end
  end

  head do
    url "https://github.com/whycorporation/whycodes.git", branch: "main"
    depends_on "rust" => :build
  end

  livecheck do
    url "https://github.com/whycorporation/whycodes/releases/latest"
    strategy :github_latest
  end

  def install
    if build.head?
      system "cargo", "install", "--locked", "--features", "bundled-sqlite", *std_cargo_args(path: "crates/cli")
    elsif File.exist?("whycodes")
      bin.install "whycodes"
    elsif File.exist?("whycode")
      # v0.1.0 archives still ship the pre-rebrand binary name.
      bin.install "whycode" => "whycodes"
    else
      odie "archive did not contain a whycodes binary"
    end
    generate_completions_from_executable(bin/"whycodes", "completions")
  end

  def caveats
    <<~EOS
      The binary is unsigned, so macOS Gatekeeper may warn on first run.
      Update with `brew upgrade whycodes` rather than `whycodes upgrade`.
    EOS
  end

  test do
    assert_match "whycodes", shell_output("#{bin}/whycodes --version")
    assert_match "whycodes", shell_output("#{bin}/whycodes completions bash")
  end
end
